content.content:
1	@import "tailwindcss";
2	
3	@theme {
4	  --font-sans: "Plus Jakarta Sans", ui-sans-serif, system-ui, sans-serif;
5	  --font-display: "Fraunces", ui-serif, Georgia, serif;
6	
7	  --color-paper: #faf7f2;
8	  --color-ink: #1f2430;
9	  --color-muted: #5b6170;
10	
11	  --color-theorist: #4f46e5;
12	  --color-theorist-soft: #eef2ff;
13	  --color-practitioner: #0f9d76;
14	  --color-practitioner-soft: #e7f7f1;
15	  --color-skeptic: #d9480f;
16	  --color-skeptic-soft: #fff1e8;
17	}
18	
19	body {
20	  background: var(--color-paper);
21	  color: var(--color-ink);
22	  font-family: var(--font-sans);
23	  -webkit-font-smoothing: antialiased;
24	}
25	
26	:focus-visible {
27	  outline: 3px solid var(--color-theorist);
28	  outline-offset: 3px;
29	  border-radius: 12px;
30	}
31	
32	@keyframes bar {
33	  0%, 100% { transform: scaleY(0.3); }
34	  50% { transform: scaleY(1); }
35	}
36	.speaking-bar { animation: bar 0.9s ease-in-out infinite; transform-origin: bottom; }
37	
38	@keyframes dot {
39	  0%, 80%, 100% { opacity: 0.25; transform: translateY(0); }
40	  40% { opacity: 1; transform: translateY(-3px); }
41	}
42	.thinking-dot { animation: dot 1.2s ease-in-out infinite; }
43	
44	@keyframes ripple {
45	  0% { transform: scale(1); opacity: 0.45; }
46	  100% { transform: scale(1.6); opacity: 0; }
47	}
48	.mic-ripple { animation: ripple 1.2s ease-out infinite; }
49	
50	.flip-card { perspective: 1000px; }
51	.flip-inner { transition: transform 0.5s; transform-style: preserve-3d; }
52	.flip-card[data-flipped="true"] .flip-inner { transform: rotateY(180deg); }
53	.flip-face { backface-visibility: hidden; }
54	.flip-back { transform: rotateY(180deg); }
55	
56	@media (prefers-reduced-motion: reduce) {
57	  .speaking-bar, .thinking-dot, .mic-ripple { animation: none; }
58	  .flip-inner { transition: none; }
59	}
